import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { Redis } from 'ioredis';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false },
  max: 20
});

const redis = new Redis(process.env.REDIS_URL);

// Session validation middleware
async function validateSession(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'No session' });
  const session = await redis.get(`sess:${token}`);
  if (!session) return res.status(401).json({ error: 'Invalid session' });
  req.session = JSON.parse(session);
  next();
}

// Audit log helper - fire and forget
function auditLog(action, details) {
  redis.lpush('audit:actions', JSON.stringify({
    ts: Date.now(), action, ...details
  })).catch(() => {});
}

// User profile update endpoint
app.put('/api/users/:userId/profile', validateSession, async (req, res) => {
  const { userId } = req.params;
  const { display_name, bio, website, avatar_url } = req.body;

  // Authorization check: users can only update their own profile
  if (req.session.user_id !== userId && req.session.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  // Build dynamic UPDATE query based on provided fields
  const updates = [];
  const values = [];
  let paramIdx = 1;

  if (display_name !== undefined) {
    updates.push(`display_name = $${paramIdx++}`);
    values.push(display_name);
  }
  if (bio !== undefined) {
    updates.push(`bio = $${paramIdx++}`);
    values.push(bio);
  }
  if (website !== undefined) {
    updates.push(`website = $${paramIdx++}`);
    values.push(website);
  }
  if (avatar_url !== undefined) {
    updates.push(`avatar_url = $${paramIdx++}`);
    values.push(avatar_url);
  }

  if (updates.length === 0) {
    return res.status(400).json({ error: 'No fields to update' });
  }

  values.push(userId);
  const query = `UPDATE user_profiles SET ${updates.join(', ')}, updated_at = NOW() WHERE user_id = $${paramIdx}`;

  try {
    await pool.query(query, values);
    auditLog('profile_update', { userId, fields: Object.keys(req.body) });
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: 'Update failed' });
  }
});

// Admin endpoint: bulk export user data
app.get('/api/admin/export', validateSession, async (req, res) => {
  if (req.session.role !== 'admin') {
    return res.status(403).json({ error: 'Admin only' });
  }

  const { format, sort_by, filter_status } = req.query;

  // Sort column validation via allowlist
  const allowedSorts = ['created_at', 'display_name', 'last_login'];
  const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';

  // VULNERABILITY: filter_status is interpolated directly into query
  const query = `
    SELECT u.id, u.email, u.created_at, p.display_name, p.bio
    FROM users u
    JOIN user_profiles p ON u.id = p.user_id
    WHERE u.account_status = '${filter_status || 'active'}'
    ORDER BY ${sortCol} DESC
    LIMIT 1000
  `;

  try {
    const result = await pool.query(query);

    if (format === 'csv') {
      const csv = result.rows.map(r => Object.values(r).join(',')).join('\n');
      res.setHeader('Content-Type', 'text/csv');
      res.send(csv);
    } else {
      res.json({ count: result.rows.length, data: result.rows });
    }
  } catch (err) {
    res.status(500).json({ error: 'Export failed', detail: err.message });
  }
});

// Health check
app.get('/health', async (req, res) => {
  const dbOk = await pool.query('SELECT 1').then(() => true).catch(() => false);
  const redisOk = await redis.ping().then(() => true).catch(() => false);
  res.json({ db: dbOk, redis: redisOk });
});

app.listen(3000, () => console.log('Service running on :3000'));
